Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.*;
import java.util.*;

public final class Main {
    static PrintWriter out = new PrintWriter(System.out);
    static MyReader in = new MyReader();

    public static void main(String[] args) {
        int n = in.nextInt();
        double p = in.nextDouble();
        int ans = 0;
        for (int i = 30; i >= 0; i--) {
            int next = ans + (1 << i);
            if (next < n && cal(next, n) < p) {
                ans = next;
            }
        }
        out.println(ans + 1);
        out.flush();
    }

    private static double cal(int m, int n) {
        long total = comb(n, 3);
        double res = 0.0;
        res += (double) comb(m, 3);
        res += (double) comb(m, 2) * comb(n - m, 1);
        res += 0.5 * comb(m, 1) * comb(n - m, 2);
        return res / total;
    }

    private static long comb(int n, int c) {
        if (c > n) return 0;
        if (c == n) return 1;
        long ans = 1L;
        for (int i = 0; i < c; i++) ans *= (n - i);
        for (int i = 1; i <= c; i++) ans /= i;
        return ans;
    }

    static class MyReader {
        BufferedReader br;
        StringTokenizer st;
        MyReader() { br = new BufferedReader(new InputStreamReader(System.in)); }
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try { st = new StringTokenizer(br.readLine()); } catch (IOException e) { e.printStackTrace(); }
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
    }
}
